<script setup>
import { computed } from 'vue'
const props = defineProps({ row: { type: Object, required: true }, sources: { type: Array, default: () => [] }, elements: { type: Array, default: () => [] }, calculations: { type: Array, default: () => [] }, measurement: { type: Object, required: true }, currency: { type: String, default: '' } })
const emit = defineEmits(['touch', 'source', 'library', 'market'])
const part = key => props.row.result?.breakdown?.find(item => item.key === key)
const contribution = key => part(key)?.amount
const money = value => value == null ? '—' : Number(value).toLocaleString('ru-RU', { maximumFractionDigits: 4 })
const methods = { manual: 'Задать цену вручную', markup: 'Наценка, %', margin: 'Маржа, %', absolute: 'Надбавка суммой', saved: 'Из сохранённого расчёта' }
const touch = () => emit('touch')
const snapshot = value => JSON.parse(JSON.stringify(value))
function changeMethod() { if (props.row.method === 'manual') props.row.rounding_step = 0; touch() }
function rebase(element) { element.currency_id = props.row.currency_id; element.measurement = snapshot(props.measurement); touch() }
function addElement(id) {
    const source = props.elements.find(item => item.id === Number(id))
    if (!source) return
    props.row.elements.push({ element_id: source.id, element_revision: source.revision, name: source.name, kind: source.kind, value: source.value, percentage_base: source.percentage_base || 'running_cost', includes_vat: source.includes_vat ?? false, vat_rate: source.vat_rate ?? 0, enabled: true, currency_id: source.currency_id, measurement: snapshot(source.measurement) })
    touch()
}
function move(index, offset) {
    const next = index + offset
    if (next < 0 || next >= props.row.elements.length) return
    const [element] = props.row.elements.splice(index, 1)
    props.row.elements.splice(next, 0, element); touch()
}
function selectCalculation(value) {
    const [kind, id] = value.split(':')
    props.row.saved_calculation_id = kind === 'workspace' ? Number(id) : null
    props.row.calculation_id = kind === 'legacy' ? Number(id) : null
    touch()
}
function available(element) {
    return element.kind === 'percent' || (Number(element.currency_id) === Number(props.row.currency_id) && Number(element.measurement?.measure_id) === Number(props.measurement.measure_id) && String(element.measurement?.unit_label) === String(props.measurement.unit_label) && Number(element.measurement?.kilograms_per_unit) === Number(props.measurement.kilograms_per_unit))
}
const selectedSource = computed(() => props.sources.find(source => source.key === props.row.source_key))
const knownSourceVat = computed(() => selectedSource.value?.kind === 'quotation' && selectedSource.value.price_includes_vat != null && selectedSource.value.vat_rate != null)
const sourceVatDiffers = computed(() => knownSourceVat.value && (Boolean(props.row.source_includes_vat) !== selectedSource.value.price_includes_vat || Number(props.row.source_vat_rate) !== Number(selectedSource.value.vat_rate)))
const sourceVatLabel = computed(() => knownSourceVat.value ? `${selectedSource.value.price_includes_vat ? 'С НДС' : 'Без НДС'} · ставка ${money(selectedSource.value.vat_rate)}%` : '')
const sourceWarning = computed(() => {
    const source = selectedSource.value
    if (!source) return ''
    if (source.is_current === false) return 'Предложение ещё не действует или срок истёк. Проверьте даты во вкладке «Маркет».'
    if (!source.currency_id) return source.kind === 'quotation' ? 'В предложении не указана валюта. Заполните её во вкладке «Маркет».' : 'В закупке не указана валюта. Исправьте закупку или выберите другой источник.'
    if (Number(source.currency_id) !== Number(props.row.currency_id)) return `Источник в ${source.currency_code}, расчёт в ${props.currency}. Выберите валюту источника в поле «Валюта расчёта» или другой источник. Автоматической конвертации нет.`
    return ''
})
const sourceLabel = source => `${source.kind === 'purchase' ? 'Закупка' : 'Предложение'} · ${source.supplier || 'Без поставщика'} · ${money(source.price)} ${source.currency_code || 'валюта не указана'} / ${money(source.denominator)} ${source.unit_label || '?'} · ${String(source.date || '').slice(0, 10)}${source.is_current === false ? ' · не действует' : ''}`
</script>

<template>
    <div class="construction">
        <div class="chain-toolbar"><label>Способ <select v-model="row.method" :disabled="row.busy" aria-label="Способ расчёта" @change="changeMethod"><option v-for="(label, value) in methods" :key="value" :value="value">{{ label }}</option></select></label><span>{{ row.method === 'manual' ? 'Прямой ввод цены: закупка и расходы не участвуют.' : row.method === 'saved' ? 'Фиксированный результат сохранённого расчёта.' : `Все суммы за 1 ${measurement.unit_label}, ${currency}. Элементы применяются слева направо.` }}</span><button type="button" class="link" @click="emit('library')">Библиотека элементов ↗</button></div>
        <div class="chain" :aria-label="`Конструкция цены · ${row.target_name || 'новый расчёт'}`">
            <template v-if="row.method === 'manual'">
                <article class="cube base-cube"><header><span class="step">01</span>Цена вручную</header><label>Сумма, {{ currency }}<input v-model="row.amount" :disabled="row.busy" type="number" min="0" step="0.0001" aria-label="Цена" @input="touch"></label><label class="check"><input v-model="row.amount_includes_vat" :disabled="row.busy" type="checkbox" @change="touch">Введена с НДС</label><small>Без привязки к закупке</small><footer>{{ money(part('manual')?.subtotal) }} <span>без НДС · до округления</span></footer></article>
            </template>
            <article v-else-if="row.method === 'saved'" class="cube source-cube"><header><span class="step">01</span>Сохранённый расчёт</header><select :value="row.saved_calculation_id ? `workspace:${row.saved_calculation_id}` : row.calculation_id ? `legacy:${row.calculation_id}` : ''" :disabled="row.busy" aria-label="Сохранённый расчёт" @change="selectCalculation($event.target.value)"><option value="" disabled>Выберите расчёт</option><option v-for="item in calculations" :key="`${item.archive_source}:${item.id}`" :value="`${item.archive_source}:${item.id}`">{{ item.name || `Расчёт №${item.id}` }} · {{ item.scope === 'entity' ? 'Entity' : 'Общий' }}</option></select><small>Доступны только расчёты с подходящим назначением.</small></article>
            <template v-else>
                <article class="cube source-cube"><header><span class="step">01</span>Цена закупки</header><select v-model="row.source_key" :disabled="row.busy" aria-label="Источник себестоимости" @change="emit('source')"><option value="" disabled>Закупка или предложение</option><option value="manual">Ручная закупочная цена</option><option v-for="source in sources" :key="source.key" :value="source.key" :disabled="source.is_current === false">{{ sourceLabel(source) }}</option></select><label v-if="row.source_key === 'manual'">Закупочная сумма, {{ currency }} / {{ measurement.unit_label }}<input v-model="row.purchase_amount" :disabled="row.busy" type="number" min="0" step="0.0001" aria-label="Ручная закупочная цена" @input="touch"></label><small v-else class="source-caption">{{ selectedSource ? sourceLabel(selectedSource) : 'Выберите источник' }}</small><div v-if="sourceWarning" class="context-warning" role="status">{{ sourceWarning }}<button v-if="selectedSource?.kind === 'quotation' && (!selectedSource.currency_id || selectedSource.is_current === false)" type="button" :disabled="row.busy" @click="emit('market')">Открыть «Маркет» ↗</button></div><small v-if="knownSourceVat">{{ sourceVatLabel }}</small><small v-else-if="selectedSource?.kind === 'quotation'">НДС предложения не указан — проверьте блок «Входящий НДС».</small><footer>{{ money(row.result?.source_gross) }} <span>{{ currency }} / {{ measurement.unit_label }}</span></footer></article>
                <span class="connector" aria-hidden="true">→</span>
                <article class="cube"><header><span class="step">02</span>Входящий НДС</header><label class="check"><input v-model="row.source_includes_vat" :disabled="row.busy" type="checkbox" @change="touch">Выделить из закупки</label><label>Ставка, %<input v-model="row.source_vat_rate" :disabled="row.busy || !row.source_includes_vat" type="number" min="0" max="100" step="0.0001" @input="touch"></label><small>НДС −{{ money(row.result?.source_vat) }}</small><div v-if="sourceVatDiffers" class="context-warning">В предложении: {{ sourceVatLabel }}. Условия расчёта отличаются.<button type="button" :disabled="row.busy" @click="emit('source')">Взять НДС предложения</button></div><footer>{{ money(row.result?.purchase_net) }} <span>закупка без НДС</span></footer></article>
                <template v-for="(element, index) in row.elements" :key="index">
                    <span class="connector" aria-hidden="true">＋</span><article class="cube extra-cube" :class="{ disabled: !element.enabled }"><header><label class="check"><input v-model="element.enabled" :disabled="row.busy" type="checkbox" :aria-label="`Участвует в расчёте: ${element.name}`" @change="touch"><span>{{ String(index + 3).padStart(2, '0') }}</span></label><div class="cube-tools"><button type="button" :disabled="row.busy || index === 0" :aria-label="`Переместить ${element.name} влево`" @click="move(index, -1)">←</button><button type="button" :disabled="row.busy || index === row.elements.length - 1" :aria-label="`Переместить ${element.name} вправо`" @click="move(index, 1)">→</button><button type="button" :disabled="row.busy" :aria-label="`Убрать ${element.name} из расчёта`" @click="row.elements.splice(index, 1); touch()">×</button></div></header><input v-model="element.name" :disabled="row.busy" maxlength="120" aria-label="Название элемента" @input="touch"><div class="pair"><input v-model="element.value" :disabled="row.busy" type="number" min="0" step="0.0001" aria-label="Величина элемента" @input="touch"><select v-model="element.kind" :disabled="row.busy" aria-label="Формат элемента" @change="element.kind === 'percent' && (element.includes_vat = false); touch()"><option value="fixed">{{ currency }}</option><option value="percent">%</option></select></div><select v-if="element.kind === 'percent'" v-model="element.percentage_base" :disabled="row.busy" aria-label="База процента" @change="touch"><option value="purchase_net">От закупки без НДС</option><option value="running_cost">От суммы слева</option></select><small v-else>Сумма за 1 {{ element.measurement?.unit_label || measurement.unit_label }}</small><div v-if="!available(element)" class="context-warning">Валюта или единица элемента отличается от расчёта.<button type="button" :disabled="row.busy" @click="rebase(element)">Использовать сумму как {{ currency }} / {{ measurement.unit_label }}</button></div><details v-if="element.kind === 'fixed'"><summary>НДС расхода</summary><label class="check"><input v-model="element.includes_vat" :disabled="row.busy" type="checkbox" @change="touch">Сумма с НДС</label><label>Ставка, %<input v-model="element.vat_rate" :disabled="row.busy || !element.includes_vat" type="number" min="0" max="100" step="0.0001" @input="touch"></label></details><small>{{ element.enabled ? 'Включён' : 'Не участвует' }} · {{ element.element_id ? 'Копия из библиотеки' : 'Элемент расчёта' }}</small><footer>＋{{ money(contribution(`element:${index}`)) }} <span>вклад без НДС</span><span>Затраты → {{ money(part(`element:${index}`)?.subtotal) }} {{ currency }}</span></footer></article>
                </template>
                <span class="connector" aria-hidden="true">＋</span><article class="cube add-cube"><header>Добавить расход</header><select value="" :disabled="row.busy || !elements.length" aria-label="Добавить элемент из библиотеки" @change="addElement($event.target.value); $event.target.value = ''"><option value="">Из библиотеки…</option><option v-for="element in elements" :key="element.id" :value="element.id" :disabled="!available(element)">{{ element.name }} · {{ money(element.value) }} {{ element.kind === 'percent' ? '%' : currency }}{{ !available(element) ? ' (другая валюта / единица)' : '' }}</option></select><button type="button" :disabled="row.busy" @click="row.elements.push({ element_id: null, element_revision: null, name: 'Дополнительный расход', kind: 'fixed', value: 0, percentage_base: 'running_cost', includes_vat: false, vat_rate: 0, enabled: true, currency_id: row.currency_id, measurement: snapshot(measurement) }); touch()">＋ Свой элемент</button><small>Логистика, хранение, реклама, услуги…</small></article>
                <span class="connector" aria-hidden="true">→</span><article class="cube"><header>Прибыль</header><label>{{ row.method === 'margin' ? 'Маржа, % от продажи' : row.method === 'markup' ? 'Наценка, % к затратам' : `Надбавка, ${currency}` }}<input v-model="row.parameter" :disabled="row.busy" type="number" min="0" :max="row.method === 'margin' ? 99.9999 : undefined" step="0.0001" aria-label="Параметр расчёта" @input="touch"></label><small>{{ row.method === 'margin' ? 'Продажа = затраты ÷ (1 − маржа / 100)' : row.method === 'markup' ? 'Продажа = затраты × (1 + наценка / 100)' : 'Продажа = затраты + надбавка' }}</small><footer>＋{{ money(row.result?.profit_before_rounding) }} <span>без НДС</span></footer></article>
            </template>
            <span class="connector" aria-hidden="true">→</span><article class="cube vat-cube"><header>Исходящий НДС</header><label>Ставка, %<input v-model="row.vat_rate" :disabled="row.busy" type="number" min="0" max="100" step="0.0001" aria-label="НДС, %" @input="touch"></label><small>{{ row.method === 'manual' && row.amount_includes_vat ? 'Выделяется из введённой цены' : 'Начисляется на цену без НДС' }}</small><footer>{{ money(contribution('sale_vat')) }} <span>{{ currency }} · до округления</span></footer></article>
            <span class="connector" aria-hidden="true">→</span><article class="cube"><header>Округление</header><label>Шаг вверх, {{ currency }}<input v-model="row.rounding_step" :disabled="row.busy" type="number" min="0" step="0.0001" aria-label="Шаг округления" @input="touch"></label><small>0 — без округления</small><footer>＋{{ money(contribution('rounding')) }} <span>с НДС</span></footer></article>
            <span class="connector" aria-hidden="true">＝</span><article class="cube total-cube"><header>Итоговая цена</header><strong>{{ money(row.result?.price_gross) }} <small>{{ currency }}</small></strong><small>С НДС / {{ measurement.unit_label }}</small><dl><div><dt>Без НДС</dt><dd>{{ money(row.result?.price_net) }}</dd></div><div><dt>НДС после округления</dt><dd>{{ money(row.result?.vat_amount) }}</dd></div><template v-if="row.result?.cost_net != null"><div><dt>Все затраты</dt><dd>{{ money(row.result.cost_net) }}</dd></div><div><dt>Прибыль</dt><dd>{{ money(row.result.profit) }}</dd></div><div><dt>Маржа</dt><dd>{{ money(row.result.margin_percent) }}%</dd></div></template></dl><small v-if="!row.result" class="pending">Нажмите «Рассчитать»</small></article>
        </div>
        <details v-if="row.result?.breakdown?.length" class="breakdown"><summary>Расшифровка всех элементов · {{ row.result.breakdown.length }} шагов</summary><table><thead><tr><th>Элемент</th><th>Формула</th><th>Изменение, {{ currency }}</th><th>Результат, {{ currency }}</th></tr></thead><tbody><tr v-for="(part, index) in row.result.breakdown" :key="part.key || index"><td>{{ part.label }}</td><td>{{ part.formula || '—' }}</td><td>{{ money(part.amount) }}</td><td>{{ money(part.subtotal) }}</td></tr></tbody></table></details>
    </div>
</template>

<style scoped>
.construction { padding: 2px 0 6px; min-width: 0; font-size: 10px; }.chain-toolbar { display: flex; align-items: center; flex-wrap: wrap; gap: 8px; margin-bottom: 7px; color: #797281; }.chain-toolbar label { display: flex; align-items: center; gap: 5px; color: #4d4755; }.chain-toolbar select { width: 190px; }.chain-toolbar span { flex: 1; }.chain { display: flex; align-items: stretch; overflow-x: auto; overscroll-behavior-x: contain; padding: 2px 2px 9px; scrollbar-width: thin; }.cube { flex: 0 0 125px; display: flex; flex-direction: column; gap: 6px; border: 1px solid #d4d0db; border-radius: 5px; padding: 7px; background: #fff; min-width: 0; }.cube header { display: flex; align-items: center; justify-content: space-between; gap: 5px; color: #5c5367; font-size: 10px; font-weight: 600; min-height: 19px; }.cube .step { color: #a49baa; font-weight: 400; }.cube label:not(.check) { display: grid; gap: 3px; font-size: 9px; color: #80768a; }.cube small { color: #8d8295; font-size: 9px; line-height: 1.4; }.cube footer { margin-top: auto; padding-top: 5px; border-top: 1px solid #efedf2; font-variant-numeric: tabular-nums; font-weight: 600; }.cube footer span { display: block; font-size: 9px; font-weight: 400; color: #8d8295; }.source-cube { flex-basis: 180px; }.source-caption { display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }.connector { flex: 0 0 20px; align-self: center; text-align: center; color: #9d91ac; font-size: 14px; }.extra-cube { flex-basis: 146px; border-color: #c9c1d5; background: #fdfcfe; }.context-warning { color: #a85b35; font-size: 9px; }.context-warning button { white-space: normal; margin-top: 3px; font-size: 9px; width: 100%; }.extra-cube.disabled { opacity: .6; background: #f0edf2; }.cube-tools { display: flex; gap: 2px; }.cube-tools button { padding: 0; min-height: 19px; width: 20px; }.pair { display: grid; grid-template-columns: minmax(0, 1fr) 55px; gap: 4px; }.check { display: flex; align-items: center; gap: 4px; font-size: 9px; }.add-cube { border-style: dashed; background: #faf9fc; }.add-cube button { font-size: 9px; padding-inline: 3px; }.total-cube { flex-basis: 150px; border-color: #aebad1; background: #f5f8ff; }.total-cube strong { color: #334c75; font-size: 18px; font-variant-numeric: tabular-nums; }.total-cube dl { margin: 0; padding-top: 5px; border-top: 1px solid #dfe5f0; font-size: 9px; }.total-cube dl div { display: flex; justify-content: space-between; gap: 8px; margin: 2px 0; }.total-cube dt { color: #7a7f8b; }.total-cube dd { margin: 0; font-variant-numeric: tabular-nums; }.total-cube .pending { color: #9b762e; }button, input, select { font: inherit; }button { min-height: 24px; padding: 2px 6px; border: 1px solid #d6d3d9; border-radius: 4px; background: #fff; cursor: pointer; white-space: nowrap; }button:hover:enabled { background: #f0edf6; }button:disabled { opacity: .45; cursor: default; }input:not([type=checkbox]), select { min-height: 25px; width: 100%; min-width: 0; padding: 3px 5px; border: 1px solid #d7d4dc; border-radius: 4px; color: #38343f; background: #fff; box-sizing: border-box; }input:disabled, select:disabled { background: #f4f3f5; color: #625b6a; }input[type=checkbox] { accent-color: #5077b8; width: 12px; height: 12px; flex: none; }.link { border: none; background: transparent; color: #4266a1; padding: 2px 0; }summary { cursor: pointer; color: #4266a1; font-size: 9px; }details label { margin-top: 4px; }.breakdown { margin: 3px 2px 0; }.breakdown summary { font-size: 10px; padding: 3px 0; }table { width: 100%; border-collapse: collapse; font-size: 10px; text-align: left; margin-top: 5px; }th { background: #f0eef3; color: #77727c; font-size: 9px; font-weight: 600; }th, td { padding: 4px 7px; border-bottom: 1px solid #e0dde6; }td:nth-last-child(-n+2), th:nth-last-child(-n+2) { text-align: right; font-variant-numeric: tabular-nums; }tr:nth-child(even) { background: #faf9fb; }:is(button, input, select, summary):focus-visible { outline: 2px solid #739ade; outline-offset: 2px; }
</style>
